$0\leqq\theta<2\pi$ とする．
\begin{enumerate}
  \item 方程式 $2\cos^2\theta+3\sin\theta-3=0$ を解け．
  \item 不等式 $\cos2\theta+3\sin\theta-2>0$ を解け．
  \item 方程式 $\tan\theta+\dfrac{1}{\tan\theta}=4$ を解け．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq\theta<2\pi$ のとき，$\sin3\theta=\sin\theta$ を解け．
  \item $0\leqq x<2\pi,\ 0\leqq y<2\pi$ のとき，連立方程式 $\sin x+\sin y=1,\ \cos x+\cos y=\sqrt3$ を解け．
\end{enumerate}

実数 $x,y$ が $\tan x+\tan y=4$，$\tan(x+y)=-2$ を満たす．
\begin{enumerate}
  \item $\tan x\tan y$ の値を求めよ．
  \item $\dfrac{\cos(x-y)}{\cos(x+y)}$ の値を求めよ．
  \item $\sin2x+\sin2y$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq x\leqq\frac\pi2$ のとき，$f(x)=\sin^2x+2\sqrt3\sin x\cos x+3\cos^2x$ の最大値・最小値とそのときの $x$ を求めよ．
  \item $0\leqq\theta\leqq\pi$ のとき，方程式 $\sin\theta+\sqrt3\cos\theta=k$ の解の個数を，実数 $k$ の値によって分類せよ．
\end{enumerate}

$0\leqq\theta\leqq\pi$ とし，$t=\sin\theta+\cos\theta$ とおく．
\begin{enumerate}
  \item $t$ の取り得る値の範囲を求めよ．
  \item $y=\sin2\theta+2a(\sin\theta+\cos\theta)$ を $t$ と $a$ で表せ．
  \item $y$ の最小値を実数 $a$ の値によって場合分けして求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\cos20^\circ\cos40^\circ\cos80^\circ$ の値を求めよ．
  \item $\cos36^\circ-\cos72^\circ$ の値を求めよ．
  \item $0\leqq x\leqq\pi,\ 0\leqq y\leqq\pi$ のとき，$\sin x+\sin y\leqq2\sin\dfrac{x+y}{2}$ を示せ．
\end{enumerate}

$\triangle ABC$ において $A=120^\circ$ とする．
\begin{enumerate}
  \item $\sin B+\sin C$ の取り得る値の範囲を求めよ．
  \item $\sin B\sin C$ の取り得る値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq x\leqq\pi$ のとき，$y=3\sin^2x+2\sqrt3\sin x\cos x+\cos^2x$ の最大値と最小値，そのときの $x$ を求めよ．
  \item 点 $(x,y)$ が原点を中心とする半径1の円周上を動くとき，$xy(x+y+1)$ の最大値と最小値を求めよ．
\end{enumerate}

$0\leqq\theta\leqq\pi$ とし，$f(\theta)=a(\sin\theta-\cos\theta)+\sin2\theta$ とする．
\begin{enumerate}
  \item $t=\sin\theta-\cos\theta$ のとりうる値の範囲を求め，$t$ の値1つに対応する $\theta$ の個数を調べよ．
  \item $\sin2\theta$ を $t$ で表せ．
  \item 方程式 $f(\theta)=0$ が相異なる3つの解をもつような $a$ の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $\dfrac1{\sin x}+\dfrac1{\sin3x}=4$ の $0<x<\dfrac34\pi$ における解の個数を求めよ．
  \item $x,y,z$ は1と異なる正の数で，
  \[ \log_xy+\log_yz+\log_zx=\frac{31}6,\quad\log_yx+\log_zy+\log_xz=\frac{41}6,\quad xyz=2^{90},\quad x\leqq y\leqq z \]
  をみたす．$x,y,z$ を求めよ．
\end{enumerate}

$a$ を実数，$0\leqq\theta\leqq\pi$ とする．$\theta$ についての方程式 $\cos2\theta+4a\sin\theta+3a-2=0$ について，
\begin{enumerate}
  \item この方程式が解をもつための $a$ の範囲を求めよ．
  \item この方程式がちょうど2個の解をもつための $a$ の範囲を求めよ．
\end{enumerate}

原点中心，半径1の円 $S$ と，2点 A$(0,3)$，B$(0,-3)$ を考える．$S$ 上の点 P$(\cos\theta,\sin\theta)$ に対し，直線 AP，BP と $x$ 軸との交点をそれぞれ X$_\mathrm A$，X$_\mathrm B$ とする．
\begin{enumerate}
  \item X$_\mathrm A$，X$_\mathrm B$ の $x$ 座標を $\theta$ で表せ．
  \item $0<\theta<\dfrac\pi2$ のとき，線分 X$_\mathrm A$X$_\mathrm B$ の長さの最大値を求めよ．
\end{enumerate}

$n$ を正の整数とし，$\cos n\theta=p_n(\cos\theta)$ をみたす多項式 $p_n(x)$ を考える．
\begin{enumerate}
  \item $p_n(x)$ の定数項と1次の係数を求めよ．
  \item $(1-x^2)p_n''(x)-xp_n'(x)+n^2p_n(x)=0$ を示せ．
  \item $p_n(x)$ の2次の係数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq\theta\leqq\pi$ で $2\cos\theta-\sin\theta=1$ が成り立つとき，$\tan\theta$ の値を求めよ．
  \item 方程式 $\cos2x-3\sin x=2$（$0\leqq x<2\pi$）を解け．
  \item $0\leqq\theta\leqq\pi$ のとき，$\sin3\theta=\sin\theta$ を満たす $\theta$ をすべて求めよ．
  \item 連立方程式 $\sin x+\sin y=1$，$\cos x+\cos y=\sqrt3$ を満たす $x,y$ を求めよ（$0\leqq x<2\pi$，$0\leqq y<2\pi$）．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq\theta\leqq\pi$ のとき，$\cos2\theta-3\cos\theta+2\leqq0$ を解け．また，$\sin\theta-\sqrt3\cos\theta\geqq1$ を解け．
  \item $0\leqq x<2\pi$ のとき，$\sin2x-(\sin x+\cos x)-1<0$ を解け．
  \item $0\leqq x\leqq2\pi$ のとき，不等式 $\cos3x+\cos x>\cos2x$ を解け．
\end{enumerate}

\begin{enumerate}
  \item $0<x<\dfrac\pi2$ の範囲で方程式 $\sin4x=\cos x$ を解け．
  \item $\sin\dfrac\pi{10}$ と $\cos\dfrac\pi5$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0\leqq\theta\leqq\pi$ のとき，関数 $y=4\sin\theta\cos\theta-2\sqrt2(\sin\theta-\cos\theta)+1$ の最大値・最小値と，そのときの $\theta$ を求めよ．
  \item $0\leqq\theta\leqq\dfrac\pi2$ のとき，関数 $y=3\sin^2\theta+2\sqrt3\sin\theta\cos\theta+\cos^2\theta$ の最大値・最小値と，そのときの $\theta$ を求めよ．
\end{enumerate}

$0\leqq x\leqq\dfrac{4\pi}3$ とする．
\begin{enumerate}
  \item $\sin x=t$ を満たす $x$ がちょうど1個となるような $t$ の値の範囲を求めよ．
  \item 方程式 $3\cos2x+4\sin x-k=0$ が $0\leqq x\leqq\frac{4\pi}3$ においてちょうど2個の解をもつような実数 $k$ の値をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item (i) 加法定理を利用して，$\cos\alpha-\cos\beta=-2\sin\dfrac{\alpha+\beta}2\sin\dfrac{\alpha-\beta}2$ を証明せよ．\\
  (ii) $0^\circ<\theta<90^\circ$ のとき，$\cos2\theta=\cos3\theta$ を満たす $\theta$ を求めよ．
  \item (1)(ii) で求めた $\theta$ に対して，$\cos\theta$ の値を求めよ．
  \item 3つの三角比の積 $\cos12^\circ\cos48^\circ\cos72^\circ$ の値を求めよ．
\end{enumerate}

三角形 ABC の3つの内角を $A,B,C$ とする．
\begin{enumerate}
  \item $A=\dfrac{2\pi}3$ のとき，$\sin B\sin C$ の値の範囲を求めよ．
  \item $A$ が一定のとき，$\cos B+\cos C$ の値の範囲を $A$ で表せ．
  \item $A$ が一定のとき，$\cos B\cos C$ の値の範囲を $A$ で表せ．
\end{enumerate}

直線 $l$ 上にない点 A から $l$ に垂線 AH を下ろし，線分 AH 上に点 B をとる．AH$=4$，BH$=1$ とする．点 P は $l$ 上を H から左に動き，PH$=x$（$x>0$），$\angle$APB$=\theta$ とおく．
\begin{enumerate}
  \item $\tan\theta$ を $x$ で表せ．
  \item $\tan\theta$ の最大値と，そのときの $x$ を求めよ．
  \item $\tan\theta\geqq\dfrac23$ となる $x$ の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\sin\theta\neq0$ のとき，$\displaystyle\sum_{k=1}^n\cos2k\theta=\frac{\sin(2n+1)\theta-\sin\theta}{2\sin\theta}$ を示せ．
  \item $\displaystyle\sum_{k=1}^{50}\cos\frac{2k\pi}{101}$ の値を求めよ．
  \item $\displaystyle\sum_{k=1}^{50}\cos^2\frac{k\pi}{101}$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 加法定理を用いて $\cos(n+2)\theta+\cos n\theta=2\cos\theta\cos(n+1)\theta$ を導け．
  \item 自然数 $n$ に対し $\cos n\theta=T_n(\cos\theta)$ を満たす整数係数の $n$ 次式 $T_n(x)$ が存在し，最高次の係数が $2^{n-1}$ であることを示せ．
  \item $\cos20^\circ$ は無理数であることを示せ．
\end{enumerate}

$a,b$ を実数とする．関数 $f(\theta)=a\cos^2\theta+4\sin\theta\cos\theta+b\sin^2\theta$（$0\leqq\theta<2\pi$）について，
\begin{enumerate}
  \item $f(\theta)$ の最小値 $m$，最大値 $M$ を $a,b$ で表せ．
  \item すべての $\theta$ に対して $f(\theta)\geqq0$ となる条件を $a,b$ で表せ．
  \item $f(\theta)$ が $\theta$ の値によって正の値も負の値もとる条件を $a,b$ で表せ．
\end{enumerate}

点 O を中心とした半径1の円を $S$ とする．
\begin{enumerate}
  \item $S$ の周上に3点 P，Q，R がこの順に反時計回りに並び，$\alpha=\angle$POQ，$\beta=\angle$QOR（$0<\alpha<\pi$，$0<\beta<\pi$，$\alpha+\beta>\pi$ も可）とする．$\triangle$PQR の面積は $\frac12\{\sin\alpha+\sin\beta-\sin(\alpha+\beta)\}$ で与えられることを示せ．
  \item $S$ の周上に5点 A，B，C，D，X がこの順に反時計回りに並んでいる．$\angle$AOB$=\frac\pi3$，$\angle$BOC$=\frac\pi2$，$\angle$COD$=\frac\pi3$ であり，X は D と A の間を動く．$\triangle$XAB と $\triangle$XCD の面積の和の最大値と，そのときの $\angle$AOX を求めよ．
\end{enumerate}

角 $\beta$ は $0^\circ<\beta<90^\circ$，$\tan\beta=\dfrac13$ を満たしている．次の問に答えなさい．
\begin{enumerate}
  \item $\tan2\beta$，$\tan3\beta$，$\tan4\beta$ を求めなさい．さらに，$\tan5\beta=-\dfrac{79}3$ であることを示しなさい．
  \item $18^\circ<\beta<27^\circ$ を示しなさい．
  \item $0<x<\frac\pi2$ で $\tan x>x$ であること，および $\pi>3$ を用いて，$18^\circ<\beta<19^\circ$ を示しなさい．
\end{enumerate}

以下の問いに答えよ．
\begin{enumerate}
  \item $0\leqq x\leqq2\pi$ の範囲で $\sin(\pi\cos x)=\dfrac12$ を満たす $x$ の個数を求めよ．
  \item $0\leqq x\leqq2\pi$ の範囲で $\cos(\pi\sin x)=\sin x$ を満たす $x$ の個数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\sin(x+y)-\sin x-\sin y=-4\sin\dfrac{x+y}2\sin\dfrac x2\sin\dfrac y2$ を示せ．
  \item $x,y$ の動く範囲を $0\leqq x\leqq2\pi$，$0\leqq y\leqq2\pi$ とするとき，不等式 $\sin(x+y)\geqq\sin x+\sin y$ の表す領域を平面上に図示せよ．
\end{enumerate}

\begin{enumerate}
  \item $\tan\theta\tan(60^\circ-\theta)\tan(60^\circ+\theta)=\tan3\theta$ を示せ（各項は定義されるとする）．
  \item $\tan20^\circ\tan40^\circ\tan80^\circ$ の値を求めよ．
  \item $\tan6^\circ\tan42^\circ\tan66^\circ\tan78^\circ=1$ を示せ．
\end{enumerate}

三角形ABCにおいて，次の問に答えよ．
\begin{enumerate}
  \item $\sin A+\sin B+\sin C=4\cos\dfrac A2\cos\dfrac B2\cos\dfrac C2$ を示せ．
  \item $\cos^2A+\cos^2B+\cos^2C+2\cos A\cos B\cos C=1$ を示せ．
  \item $\cos^2A+\cos^2B+\cos^2C=1$ ならば三角形ABCは直角三角形であることを示せ．
\end{enumerate}

$\theta$ が $0\leqq\theta\leqq\dfrac\pi2$ の範囲を変化するとき，$u=2\cos\theta+\sin\theta$，$v=\cos\theta+2\sin\theta$ とする．
\begin{enumerate}
  \item 点 $(u+v,\ u-v)$ の描く図形を求めよ．
  \item 点 $(uv,\ u^2+v^2)$ の描く図形を求めよ．
\end{enumerate}

AB$=2$，AC$=1$，$\angle\mathrm{BAC}=60^\circ$ の三角形ABCに，長方形ADEFを外接させる．ただし，Bは辺DE上，Cは辺EF上にあるとする．
\begin{enumerate}
  \item $\angle\mathrm{BAD}=\theta$ とするとき，$\theta$ のとり得る範囲を求めよ．
  \item 長方形ADEFの面積の最大値と，そのときの $\theta$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $y=\dfrac{2\sin x+1}{\cos x+2}$（$0\leqq x\leqq2\pi$）のとり得る値の範囲を求めよ．
  \item $-\frac\pi2<x<\frac\pi2$，$-\frac\pi2<y<\frac\pi2$ のとき，連立方程式 $\dfrac{\sin x}{\sin y}=\sqrt2$，$\dfrac{\tan x}{\tan y}=\sqrt3$ を解け．
\end{enumerate}

$0<\alpha<\beta<2\pi$ とする．
\begin{enumerate}
  \item すべての実数 $x$ に対して $\cos x+\sqrt2\cos(x+\alpha)+\cos(x+\beta)=k$ が成り立つような $\alpha,\beta,k$ を求めよ．
  \item $\displaystyle\sum_{j=1}^6\cos\frac{2j\pi}7$ と $\displaystyle\sum_{j=1}^6\cos^2\frac{2j\pi}7$ の値を求めよ．
\end{enumerate}

三角形ABCの3つの内角 $A,B,C$ について，次を示せ．
\begin{enumerate}
  \item $\cos2A+\cos2B+\cos2C=-1-4\cos A\cos B\cos C$
  \item $\sin^2A+\sin^2B+\sin^2C=2$ ならば，三角形ABCは直角三角形である．
  \item $\sin^2A+\sin^2B+\sin^2C>2$ ならば，三角形ABCは鋭角三角形である．
\end{enumerate}

不等式 $a\sin\theta+\cos\theta<a$ ……① について，次の条件をみたす実数 $a$ の範囲をそれぞれ求めよ．
\begin{enumerate}
  \item ①をみたす $\theta$ が区間 $\frac\pi6<\theta<\frac\pi3$ に少なくとも1つある．
  \item 区間 $\frac\pi6<\theta<\frac\pi3$ のすべての $\theta$ が①をみたす．
\end{enumerate}

$\cos\alpha+\cos\beta+\cos\gamma=0$，$\sin\alpha+\sin\beta+\sin\gamma=0$ とする．次を示せ．
\begin{enumerate}
  \item $\cos2\alpha+\cos2\beta+\cos2\gamma=0$，$\sin2\alpha+\sin2\beta+\sin2\gamma=0$
  \item $\cos4\alpha+\cos4\beta+\cos4\gamma=0$
  \item $\cos6\alpha+\cos6\beta+\cos6\gamma=3\cos2(\alpha+\beta+\gamma)$
\end{enumerate}

$n$ を自然数，$0<\theta<\pi$ とする．
\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^n\sin(2k-1)\theta=\frac{\sin^2n\theta}{\sin\theta}$，$\displaystyle\sum_{k=1}^n\cos(2k-1)\theta=\frac{\sin2n\theta}{2\sin\theta}$ を示せ．
  \item $\displaystyle\sum_{k=1}^n\cos\frac{(2k-1)\pi}{2n+1}$ の値を求めよ．
\end{enumerate}

極座標で表された3点 A$\left(4,\dfrac\pi{12}\right)$，B$\left(2,\dfrac34\pi\right)$，C$\left(6,\dfrac54\pi\right)$ と極Oについて，
\begin{enumerate}
  \item 点Aの直交座標を求め，直交座標の点 $(-\sqrt6,\ -\sqrt2)$ を極座標 $(r,\theta)$（$r>0$，$0\leqq\theta<2\pi$）で表せ．
  \item 線分ABの長さと $\triangle\mathrm{OAB}$ の面積を求めよ．
  \item 極Oは $\triangle\mathrm{ABC}$ の内部にあることを示し，$\triangle\mathrm{ABC}$ の面積を求めよ．
\end{enumerate}

実数 $x,y$ が $|x|\leqq1$，$|y|\leqq1$ をみたすとする．
\begin{enumerate}
  \item 不等式 $0\leqq x^2+y^2-2x^2y^2-2xy\sqrt{1-x^2}\sqrt{1-y^2}\leqq1$ を示せ．
  \item (1) の中央の式の値が1となる $(x,y)$ の条件を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\sqrt3+i$ と $1-i$ を $r(\cos\theta+i\sin\theta)$（$r>0$，$-\pi<\theta\leqq\pi$）の形で表せ．
  \item $\dfrac{\sqrt3+i}{1-i}$ を2通りに計算して，$\cos\dfrac5{12}\pi$，$\sin\dfrac5{12}\pi$ の値を求めよ．
  \item $\tan\dfrac5{12}\pi$ の値を求めよ．
\end{enumerate}

$\tan\alpha=\dfrac12$，$\tan\beta=\dfrac15$，$\tan\gamma=\dfrac18$，$0<\alpha,\beta,\gamma<\dfrac\pi2$ とする．
\begin{enumerate}
  \item $\tan(\alpha+\beta+\gamma)$ と $\alpha+\beta+\gamma$ を求めよ．
  \item $\alpha-\beta>\beta-\gamma$ を示せ．
  \item $\beta<\dfrac\pi{12}$ を示せ．
\end{enumerate}

$0\leqq\alpha\leqq\pi$ として，$\cos\alpha=\sin2\beta$（$0\leqq\beta\leqq\pi$）をみたす $\beta$ を考える．
\begin{enumerate}
  \item $\alpha=\dfrac\pi3$ のとき，$\beta$ のとり得る値を求めよ．
  \item $0<\alpha<\pi$，$\alpha\neq\frac\pi2$ のとき，$\beta$ は2つある．小さい方を $\beta_1$，大きい方を $\beta_2$ として，$\beta_1,\beta_2$ を $\alpha$ で表せ．
  \item $y=\sin\left(\alpha+\dfrac{\beta_1}2+\dfrac{\beta_2}3\right)$ が最大となる $\alpha$ の値と最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\tan\theta$ と $\tan\varphi$ が有理数で $\tan(\theta+\varphi)$ が定義されるとき，$\tan(\theta+\varphi)$ は有理数であることを示せ．
  \item $\tan5^\circ$ は有理数でないことを示せ．
  \item $\tan15^\circ$ の値を求め，(2) と矛盾しないことを確かめよ．
\end{enumerate}

$h(t)=\cos4t-\cos3t+\cos2t-\cos t$，$f(x)=x^4-x^3-3x^2+2x+1$ とする．
\begin{enumerate}
  \item $2h(t)+1=f(2\cos t)$ を示せ．
  \item 積和公式を用いて $\cos\dfrac t2\cdot\{2h(t)+1\}=\cos\dfrac{9t}2$ を示し，$2h\left(\dfrac\pi9\right)+1=0$ を導け．
  \item $f(x)=(x-1)(x^3-3x-1)$ を示し，$2\cos\dfrac\pi9$ は方程式 $x^3-3x-1=0$ の解であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $\cos1,\cos2,\cos3,\cos4,\cos5$ のうち負となるものをすべて答え，正となるものの最小値と最大値を答えよ．
  \item $A,B$（$A\neq B$）がいずれも鋭角のとき，次の3数の最小値と最大値を答えよ．
  \[\cos\frac{A+B}2,\qquad\frac{\cos A+\cos B}2,\qquad\cos\frac A2\cos\frac B2\]
\end{enumerate}

$f(\theta)=\cos\theta\cos2\theta\cos3\theta$，$g(\theta)=\sin\theta\sin2\theta\sin3\theta$ とする．
\begin{enumerate}
  \item $f(\theta)=p+q\cos2\theta+r\cos4\theta+s\cos6\theta$ と表せることを示し，$p,q,r,s$ を求めよ．
  \item $g\left(\theta+\dfrac\pi2\right)=\cos\theta\sin2\theta\cos3\theta$ を示せ．
  \item $0\leqq\theta\leqq\pi$ のとき，方程式 $f(\theta)=g\left(\theta+\dfrac\pi2\right)$ を解け．
\end{enumerate}

$y=\sin2\theta-2a(\sin\theta+\cos\theta)+a$（$-\frac\pi4\leqq\theta\leqq\frac\pi2$），$a>0$ とする．
\begin{enumerate}
  \item $t=\sin\theta+\cos\theta$ のとり得る値の範囲を求め，$y$ を $t$ で表せ．
  \item $y$ の最小値 $m(a)$ を求めよ．
